def merge_intervals(intervals):
    """合并重叠/相邻区间。"""
    if not intervals:
        return []
    ivs = sorted(intervals, key=lambda x: x[0])
    merged = [ivs[0]]
    for start, end in ivs[1:]:
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return merged
```

