from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity):
        self.cap = capacity
        self.data = OrderedDict()

    def get(self, key):
        if key not in self.data:
            return -1
        self.data.move_to_end(key)  # Move the accessed key to the end
        return self.data[key]

    def put(self, key, value):
        if key in self.data:
            self.data.move_to_end(key)  # Move the updated key to the end
        self.data[key] = value
        if len(self.data) > self.cap:
            self.data.popitem(last=True)  # Remove the least recently used item
```

