class RateLimiter:
    def __init__(self, max_calls, window):
        self.max_calls = max_calls
        self.window = window
        self.calls = []

    def allow(self, t):
        self.calls = [c for c in self.calls if t - c <= self.window]
        if len(self.calls) >= self.max_calls:
            return False
        self.calls.append(t)
        return True
```

