def remove_adjacent_duplicates(s):
    """反复删除相邻重复对。"""
    while True:
        new_s = s.replace('AA', '').replace('BB', '').replace('CC', '').replace('DD', '').replace('EE', '').replace('FF', '').replace('GG', '').replace('HH', '').replace('II', '').replace('JJ', '').replace('KK', '').replace('LL', '').replace('MM', '').replace('NN', '').replace('OO', '').replace('PP', '').replace('QQ', '').replace('RR', '').replace('SS', '').replace('TT', '').replace('UU', '').replace('VV', '').replace('WW', '').replace('XX', '').replace('YY', '').replace('ZZ', '')
        if new_s == s:
            break
        s = new_s
    return s
